<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();$pageTitle='Account Status';$ns=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$ns->execute([$u['id']]);$userUnreadNotifications=(int)$ns->fetchColumn();require __DIR__.'/../../includes/header.php';?><div class="admin-shell user-shell"><aside class="sidebar"><?php require __DIR__ . '/../sidebar.php'; ?></aside><section class="admin-content user-content"><section class="page-hero"><div class="container"><div class="eyebrow">Account</div><h1 class="page-title">Account status.</h1><p>Your access level and booking eligibility are shown below.</p></div></section><section class="section"><div class="container narrow"><div class="panel"><span class="badge <?=$u['account_status']==='approved'?'badge-green':($u['account_status']==='rejected'?'badge-red':'badge-gold')?>"><?=e(ucwords(str_replace('_',' ',$u['account_status'])))?></span><h2 style="font-size:42px;margin-top:18px"><?=e($u['full_name'])?></h2><p><?=e($u['email'])?></p><?php if($u['account_status']==='approved'):?><p>Your account is approved. You may create and manage your own bookings.</p><a class="btn btn-gold" href="<?=url('user/bookings/create.php')?>">Create a booking</a><?php elseif($u['account_status']==='rejected'):?><p>Reason: <?=e($u['rejection_reason']??'Not provided.')?></p><?php else:?><p>Your account is waiting for management approval. Booking access will be enabled after approval.</p><?php endif;?></div></div></section></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
